 74→func loadConfigFromEnv() (Config, error) {
 75→	cfg := Config{
 76→		Addr:             getEnvDefault("ADDR", defaultAddr),
 77→		SigningSecret:    os.Getenv("SLACK_SIGNING_SECRET"),
 78→		SlackBotToken:    os.Getenv("SLACK_BOT_TOKEN"),
 79→		GitHubToken:      os.Getenv("GITHUB_TOKEN"),
 80→		AllowedRepo:      getEnvFirst("ALLOWED_REPOSITORY", "GITHUB_REPOSITORY"),
 81→		GitHubEventType:  getEnvDefault("GITHUB_EVENT_TYPE", defaultSlackEventType),
 82→		SlackAPIBaseURL:  getEnvDefault("SLACK_API_BASE_URL", defaultSlackAPIBaseURL),
 83→		GitHubAPIBaseURL: getEnvDefault("GITHUB_API_BASE_URL", defaultGitHubAPIBaseURL),
 84→		RequestTolerance: defaultRequestTolerance,
 85→	}
 86→
 87→	if tolerance := os.Getenv("SLACK_REQUEST_TOLERANCE"); tolerance != "" {
 88→		d, err := time.ParseDuration(tolerance)
 89→		if err != nil {
 90→			return Config{}, fmt.Errorf("parse SLACK_REQUEST_TOLERANCE: %w", err)
 91→		}
 92→		cfg.RequestTolerance = d
 93→	}
 94→
 95→	switch {
 96→	case cfg.SigningSecret == "":
 97→		return Config{}, errors.New("SLACK_SIGNING_SECRET is required")
 98→	case cfg.SlackBotToken == "":
 99→		return Config{}, errors.New("SLACK_BOT_TOKEN is required")
100→	case cfg.GitHubToken == "":
101→		return Config{}, errors.New("GITHUB_TOKEN is required")
102→	case cfg.AllowedRepo == "":
103→		return Config{}, errors.New("ALLOWED_REPOSITORY or GITHUB_REPOSITORY is required")
104→	default:
105→		return cfg, nil
106→	}
107→}
