158→func (h *triageHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
159→	if r.Method != http.MethodPost {
160→		http.Error(w, http.StatusText(http.StatusMethodNotAllowed), http.StatusMethodNotAllowed)
161→		return
162→	}
163→	defer r.Body.Close()
164→
165→	body, err := io.ReadAll(io.LimitReader(r.Body, h.maxBodyLen))
166→	if err != nil {
167→		log.Printf("read request body: %v", err)
168→		http.Error(w, "read request body", http.StatusBadRequest)
169→		return
170→	}
171→
172→	if err := h.verifyRequest(r, body); err != nil {
173→		log.Printf("verify slack request: %v", err)
174→		http.Error(w, http.StatusText(http.StatusUnauthorized), http.StatusUnauthorized)
175→		return
176→	}
177→
178→	var envelope slackEnvelope
179→	if err := json.Unmarshal(body, &envelope); err != nil {
180→		log.Printf("decode slack payload: %v", err)
181→		http.Error(w, "decode slack payload", http.StatusBadRequest)
182→		return
183→	}
184→
185→	switch envelope.Type {
186→	case slackEventTypeURLVerify:
187→		writeJSON(w, http.StatusOK, map[string]string{"challenge": envelope.Challenge})
188→	case slackEventTypeCallback:
189→		if err := h.handleEvent(r.Context(), envelope.Event); err != nil {
190→			log.Printf("process slack event: %v", err)
191→			http.Error(w, "process slack event", http.StatusInternalServerError)
192→			return
193→		}
194→		w.WriteHeader(http.StatusOK)
195→	default:
196→		w.WriteHeader(http.StatusOK)
197→	}
198→}
