200→func (h *triageHandler) verifyRequest(r *http.Request, body []byte) error {
201→	timestamp := r.Header.Get(slackTimestampHeader)
202→	signature := r.Header.Get(slackSignatureHeader)
203→	if timestamp == "" || signature == "" {
204→		return errors.New("missing slack signature headers")
205→	}
206→
207→	parsed, err := strconv.ParseInt(timestamp, 10, 64)
208→	if err != nil {
209→		return fmt.Errorf("invalid slack timestamp: %w", err)
210→	}
211→
212→	requestTime := time.Unix(parsed, 0)
213→	now := h.now()
214→	if absDuration(now.Sub(requestTime)) > h.cfg.RequestTolerance {
215→		return errors.New("stale slack request")
216→	}
217→
218→	mac := hmac.New(sha256.New, []byte(h.cfg.SigningSecret))
219→	if _, err := mac.Write([]byte("v0:" + timestamp + ":" + string(body))); err != nil {
220→		return fmt.Errorf("sign slack request: %w", err)
221→	}
222→	expected := "v0=" + hex.EncodeToString(mac.Sum(nil))
223→	if !hmac.Equal([]byte(expected), []byte(signature)) {
224→		return errors.New("invalid slack signature")
225→	}
226→
227→	return nil
228→}
