230→func (h *triageHandler) handleEvent(ctx context.Context, event slackEvent) error {
231→	if event.Type != slackInnerEventTypeMessage {
232→		return nil
233→	}
234→	if event.Subtype != "" || event.BotID != "" {
235→		return nil
236→	}
237→	if event.ThreadTS == "" || event.ThreadTS == event.Ts {
238→		return nil
239→	}
240→	if !slacktriage.IsTriageTrigger(event.Text) {
241→		return nil
242→	}
243→	if h.slack == nil {
244→		return errors.New("slack fetcher is not configured")
245→	}
246→	if h.github == nil {
247→		return errors.New("github dispatcher is not configured")
248→	}
249→	if event.Channel == "" {
250→		return errors.New("channel is required")
251→	}
252→
253→	parentBody, err := h.slack.FetchParentMessage(ctx, event.Channel, event.ThreadTS)
254→	if err != nil {
255→		return fmt.Errorf("fetch parent message: %w", err)
256→	}
257→
258→	metadata, err := slacktriage.ParseParentMessageMetadata(parentBody)
259→	if err != nil {
260→		return fmt.Errorf("parse parent message metadata: %w", err)
261→	}
262→	if h.cfg.AllowedRepo != "" && metadata.Repo != h.cfg.AllowedRepo {
263→		return nil
264→	}
265→
266→	payload := slacktriage.NewDispatchPayload(metadata, event.Channel, event.ThreadTS, event.User)
267→	if err := h.github.DispatchRepositoryEvent(ctx, payload); err != nil {
268→		return fmt.Errorf("dispatch repository event: %w", err)
269→	}
270→	return nil
271→}
