322→func (c *slackHTTPClient) FetchParentMessage(ctx context.Context, channel, threadTS string) (string, error) {
323→	endpoint, err := url.Parse(c.baseURL + "/conversations.replies")
324→	if err != nil {
325→		return "", fmt.Errorf("parse slack conversations.replies url: %w", err)
326→	}
327→
328→	query := endpoint.Query()
329→	query.Set("channel", channel)
330→	query.Set("ts", threadTS)
331→	query.Set("inclusive", "true")
332→	query.Set("limit", "1")
333→	endpoint.RawQuery = query.Encode()
334→
335→	//nolint:gosec // Slack API base URL is operator-configured.
336→	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint.String(), nil)
337→	if err != nil {
338→		return "", fmt.Errorf("build slack conversations.replies request: %w", err)
339→	}
340→	req.Header.Set("Authorization", "Bearer "+c.token)
341→
342→	resp, err := c.client.Do(req) //nolint:gosec // taint tracked from operator-configured base URL above
343→	if err != nil {
344→		return "", fmt.Errorf("call slack conversations.replies: %w", err)
345→	}
346→	defer resp.Body.Close()
347→
348→	if resp.StatusCode != http.StatusOK {
349→		return "", fmt.Errorf("slack conversations.replies returned %s", resp.Status)
350→	}
351→
352→	var payload struct {
353→		OK       bool   `json:"ok"`
354→		Error    string `json:"error,omitempty"`
355→		Messages []struct {
356→			Text string `json:"text"`
357→		} `json:"messages"`
358→	}
359→	if err := json.NewDecoder(resp.Body).Decode(&payload); err != nil {
360→		return "", fmt.Errorf("decode slack conversations.replies response: %w", err)
361→	}
362→	if !payload.OK {
363→		if payload.Error == "" {
364→			payload.Error = "unknown error"
365→		}
366→		return "", fmt.Errorf("slack conversations.replies error: %s", payload.Error)
367→	}
368→	if len(payload.Messages) == 0 {
369→		return "", errors.New("slack conversations.replies returned no messages")
370→	}
371→	return payload.Messages[0].Text, nil
372→}
