382→func newGitHubHTTPDispatcher(token, baseURL, eventType, repository string) *githubHTTPDispatcher {
383→	if baseURL == "" {
384→		baseURL = defaultGitHubAPIBaseURL
385→	}
386→	if eventType == "" {
387→		eventType = defaultSlackEventType
388→	}
389→	return &githubHTTPDispatcher{
390→		token:      token,
391→		baseURL:    strings.TrimRight(baseURL, "/"),
392→		eventType:  eventType,
393→		repository: repository,
394→		client:     &http.Client{Timeout: 10 * time.Second},
395→	}
396→}
