398→func (d *githubHTTPDispatcher) DispatchRepositoryEvent(ctx context.Context, payload slacktriage.DispatchPayload) error {
399→	body, err := json.Marshal(struct {
400→		EventType     string                      `json:"event_type"`
401→		ClientPayload slacktriage.DispatchPayload `json:"client_payload"`
402→	}{
403→		EventType:     d.eventType,
404→		ClientPayload: payload,
405→	})
406→	if err != nil {
407→		return fmt.Errorf("marshal github dispatch payload: %w", err)
408→	}
409→
410→	endpoint := fmt.Sprintf("%s/repos/%s/dispatches", d.baseURL, d.repository)
411→	//nolint:gosec // GitHub API base URL and repository are operator-configured.
412→	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
413→	if err != nil {
414→		return fmt.Errorf("build github dispatch request: %w", err)
415→	}
416→	req.Header.Set("Authorization", "Bearer "+d.token)
417→	req.Header.Set("Accept", "application/vnd.github+json")
418→	req.Header.Set("Content-Type", "application/json")
419→
420→	resp, err := d.client.Do(req) //nolint:gosec // taint tracked from operator-configured base URL above
421→	if err != nil {
422→		return fmt.Errorf("call github dispatch endpoint: %w", err)
423→	}
424→	defer resp.Body.Close()
425→
426→	if resp.StatusCode != http.StatusNoContent {
427→		responseBody, readErr := io.ReadAll(io.LimitReader(resp.Body, 4096))
428→		if readErr != nil {
429→			return fmt.Errorf("github dispatch failed: %s (read response): %w", resp.Status, readErr)
430→		}
431→		if len(responseBody) > 0 {
432→			return fmt.Errorf("github dispatch failed: %s: %s", resp.Status, strings.TrimSpace(string(responseBody)))
433→		}
434→		return fmt.Errorf("github dispatch failed: %s", resp.Status)
435→	}
436→
437→	return nil
438→}
