locals {
  # Common tags/labels for all resources
  common_tags = {
    ManagedBy = "Terragrunt"
    Project   = "infra/cloudflare"
  }
}

# Generated provider configuration
generate "provider" {
  path      = "provider.tf"
  if_exists = "overwrite_terragrunt"
  contents  = <<EOF
terraform {
  required_version = ">= 1.0"
  required_providers {
    cloudflare = {
      source  = "cloudflare/cloudflare"
      version = "~> 5"
    }
  }
}

provider "cloudflare" {
  # Credentials loaded from environment variables:
  # CLOUDFLARE_API_TOKEN
}
EOF
}

# Configure remote state (S3 example - adjust as needed)
remote_state {
  backend = "s3"
  generate = {
    path      = "backend.tf"
    if_exists = "overwrite_terragrunt"
  }
  config = {
    bucket                      = "tfstate-entireio-cloudflare-54c264b5571a"
    key                         = "${path_relative_to_include()}/terraform.tfstate"
    region                      = "auto"
    skip_credentials_validation = true
    skip_metadata_api_check     = true
    skip_region_validation      = true
    skip_requesting_account_id  = true
    skip_s3_checksum            = true
    use_path_style              = true
    # These should come from environment variables:
    # access_key = "<YOUR_R2_ACCESS_KEY>"
    # secret_key = "<YOUR_R2_ACCESS_SECRET>"
    endpoints = { s3 = "https://8b04592ed74a5cce30d355b07276caf3.r2.cloudflarestorage.com" }
  }
}

